def number_of_subarrays(nums, k):
    def at_most_k(limit):
        if limit < 0:
            return 0
        left = 0
        odd_count = 0
        total = 0
        for right, num in enumerate(nums):
            if num % 2 == 1:
                odd_count += 1
            while odd_count > limit:
                if nums[left] % 2 == 1:
                    odd_count -= 1
                left += 1
            total += right - left + 1
        return total

    return at_most_k(k) - at_most_k(k - 1)

